wrong.code:
// 1. Loop capture with var
for (var i = 0; i < 3; i++) {
  buttons[i].onclick = function () { alert(i); };   // all alert 3
}

// 2. Lost this in a callback
class Counter {
  count = 0;
  start() {
    setTimeout(function () { this.count++; }, 1000); // TypeError: this is undefined
  }
}

// 3. Method extracted from its object
const timer = { secs: 0, tick() { this.secs++; } };
const tick = timer.tick;
tick();                        // this is undefined → TypeError

right.code:
// 1. let gives each iteration its own binding
for (let i = 0; i < 3; i++) {
  buttons[i].onclick = () => alert(i);            // 0, 1, 2
}

// 2. Arrow inherits this from start()
class Counter {
  count = 0;
  start() {
    setTimeout(() => { this.count++; }, 1000);    // this is the Counter
  }
  // or make the method an arrow property so it can be passed around safely
  handleClick = () => { this.count++; };
}

// 3. Keep the dot, or bind
timer.tick();
const tick = timer.tick.bind(timer); tick();

// Closures as private state (the pattern behind hooks and composables)
function makeCounter() {
  let n = 0;                                      // private, survives between calls
  return { inc: () => ++n, get: () => n };
}
const c = makeCounter(); c.inc(); c.inc(); c.get(); // 2

// once() — a closure that remembers it already ran
function once(fn) {
  let done = false, result;
  return function (...args) {
    if (!done) { done = true; result = fn.apply(this, args); }
    return result;
  };
}

